// Team page hero: a vanilla WebGL2 port of React Bits "Shape Waves"
// (inspired by vercel.com/labs). The original ran on React + vgpu/WebGPU;
// this keeps its simulation and lifecycle but has no dependencies.
//
// Addition over the original: a land mask (added-assets/team/world-mask.png,
// generated by scripts/team/build-world-mask.py) so the same dot grid draws
// the map. Ripples, hover and glow are removed: the field is a quiet,
// decorative backdrop and the copy is HTML layered on top. On failure (no WebGL2, context loss) the section keeps a
// CSS gradient behind that h1; see css/team.css.

import { VERTEX_SHADER, SCENE_SHADER, INTRO_END } from './team-hero-shaders.js?v=3';

const SHAPE_MODES = Object.freeze({ mixed: 0, squares: 1, circles: 2, triangles: 3 });
const NOISE_CELLS = 32;
const TIME_RATE = 0.1;

// Must match LON_MIN/LON_MAX/LAT_MIN/LAT_MAX in scripts/team/build-world-mask.py.
const MAP_BOUNDS = Object.freeze({ lonMin: -105, lonMax: 255, latMin: -60, latMax: 80 });

const TEAM_HERO_OPTIONS = Object.freeze({
  shapes: 'mixed',
  cellSize: 9,
  mobileCellSize: 7,
  dotSize: 0.72,
  // Oxblood-warmed dark: wine land on near-black, low contrast so the map
  // reads without pulling the eye.
  color: '#2e1c1d',
  landColor: '#6e3b42',
  backgroundColor: '#1c1010',
  seaDotScale: 0.55,
  seaDotOpacity: 0.45,
  speed: 0.35,
  scale: 1,
  contrast: 0.6,
  brightness: 0.3,
  flow: 0.15,
  direction: 0,
  fade: 0.28,
  intro: true,
  introDuration: 2.4,
  maxDpr: 2,
  mobileMaxDpr: 1.5,
  mobileBreakpoint: 768,
  map: Object.freeze({
    src: 'added-assets/team/world-mask.png',
    centerLon: 75,
    centerLat: 6, // India sits above the bottom-anchored copy; ocean falls behind it
    lonSpan: 185,
    maxLatSpan: 120
  })
});

const parseColor = (value, fallback) => {
  const source = typeof value === 'string' ? value.trim() : '';
  const match = /^#?([\da-f]{3}|[\da-f]{6})$/i.exec(source) || /^#?([\da-f]{6})$/i.exec(fallback);
  let hex = match[1];
  if (hex.length === 3) hex = hex.replace(/./g, char => char + char);
  return [0, 2, 4].map(offset => parseInt(hex.slice(offset, offset + 2), 16) / 255);
};

/* ---------- WebGL helpers ---------- */

function compileProgram(gl, fragmentSource, label) {
  const build = (type, source) => {
    const shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      throw new Error(`${label} shader: ${gl.getShaderInfoLog(shader)}`);
    }
    return shader;
  };
  const program = gl.createProgram();
  gl.attachShader(program, build(gl.VERTEX_SHADER, VERTEX_SHADER));
  gl.attachShader(program, build(gl.FRAGMENT_SHADER, fragmentSource));
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    throw new Error(`${label} link: ${gl.getProgramInfoLog(program)}`);
  }
  const locations = new Map();
  const loc = name => {
    if (!locations.has(name)) locations.set(name, gl.getUniformLocation(program, name));
    return locations.get(name);
  };
  return { program, loc };
}

function createTexture(gl, { filter = gl.LINEAR } = {}) {
  const texture = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  return texture;
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.decoding = 'async';
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error(`Could not load ${src}`));
    image.src = src;
  });
}

/* ---------- Map projection ---------- */

// Screen uv -> map uv is an affine window: mapUv = offset + uv * scale.
function computeMapView(map, cssWidth, cssHeight) {
  const lonRange = MAP_BOUNDS.lonMax - MAP_BOUNDS.lonMin;
  const latRange = MAP_BOUNDS.latMax - MAP_BOUNDS.latMin;
  const aspect = cssHeight / Math.max(1, cssWidth);
  const lonSpan = Math.min(map.lonSpan, map.maxLatSpan / aspect);
  const latSpan = lonSpan * aspect;
  const scale = [lonSpan / lonRange, latSpan / latRange];
  const center = [
    (map.centerLon - MAP_BOUNDS.lonMin) / lonRange,
    (MAP_BOUNDS.latMax - map.centerLat) / latRange
  ];
  return [center[0] - scale[0] / 2, center[1] - scale[1] / 2, scale[0], scale[1]];
}

/* ---------- Component ---------- */

export function createShapeWaves(root, canvas, settings, { onReady, onError } = {}) {
  const gl = canvas.getContext('webgl2', {
    alpha: false, antialias: false, depth: false, stencil: false,
    premultipliedAlpha: false, powerPreference: 'low-power'
  });
  if (!gl) {
    onError?.(new Error('WebGL2 is not available'));
    return { destroy() {}, replay() {} };
  }

  let disposed = false;
  let failed = false;
  let frameId = 0;
  let lastFrameTime = 0;
  let time = 0;
  let drift = [0, 0];
  let dpr = 1;
  let visible = true;
  let presented = false;
  let cols = 1;
  let rows = 1;
  let cellPx = 10;
  let gridOrigin = [0, 0];
  let introStart = 0;
  let introProgress = INTRO_END;
  let introArmed = false;
  let mapView = [0, 0, 1, 1];
  let landReady = false;
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

  const isMobile = () => window.innerWidth <= settings.mobileBreakpoint;

  const scene = compileProgram(gl, SCENE_SHADER, 'scene');
  const vao = gl.createVertexArray();
  const landMask = createTexture(gl);

  // Black 1x1 land mask until the PNG arrives: everything reads as sea.
  gl.bindTexture(gl.TEXTURE_2D, landMask);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([0, 0, 0, 255]));

  const wakeRenderer = () => {
    if (disposed || failed || frameId) return;
    frameId = requestAnimationFrame(render);
  };
  const handleWake = () => wakeRenderer();

  const configureGrid = () => {
    const width = canvas.width;
    const height = canvas.height;
    const cellSize = Math.max(2, isMobile() ? settings.mobileCellSize : settings.cellSize);
    const nextCols = Math.max(1, Math.round(width / (cellSize * dpr)));
    cellPx = width / nextCols;
    const nextRows = Math.max(1, Math.floor(height / cellPx));
    gridOrigin = [0, (height - nextRows * cellPx) / 2];
    cols = nextCols;
    rows = nextRows;
  };

  const isAnimating = () =>
    visible && !document.hidden && settings.speed > 0 && !reduceMotion.matches;

  const bindTexture = (unit, texture, program, name) => {
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.uniform1i(program.loc(name), unit);
  };

  const drawScene = () => {
    const { loc } = scene;
    const [width, height] = [canvas.width, canvas.height];
    gl.useProgram(scene.program);
    gl.uniform4f(loc('uResolution'), width, height, 1 / width, 1 / height);
    gl.uniform4f(loc('uPlacement'), gridOrigin[0], gridOrigin[1], rows, introProgress);
    gl.uniform4f(loc('uGrid'), cellPx, Math.min(1, Math.max(0.1, settings.dotSize)),
      SHAPE_MODES[settings.shapes] ?? 0, cols);
    gl.uniform4f(loc('uField'), NOISE_CELLS * cellPx * Math.max(0.05, settings.scale),
      0.5 - (settings.brightness - 0.5) * 0.4, 2.8 * settings.contrast, time);
    gl.uniform3f(loc('uMotion'), drift[0], drift[1], settings.fade);
    gl.uniform3fv(loc('uColor'), parseColor(settings.color, '#2e1c1d'));
    gl.uniform3fv(loc('uLandColor'), parseColor(settings.landColor, '#6e3b42'));
    gl.uniform3fv(loc('uBackground'), parseColor(settings.backgroundColor, '#1c1010'));
    gl.uniform4fv(loc('uMapView'), mapView);
    gl.uniform2f(loc('uLand'), settings.seaDotScale, landReady ? settings.seaDotOpacity : 1);
    bindTexture(0, landMask, scene, 'uLandMask');
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  };

  const drawFrame = () => {
    gl.bindVertexArray(vao);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, canvas.width, canvas.height);
    drawScene();
  };

  function render(now) {
    frameId = 0;
    if (disposed || failed) return;
    const deltaSeconds = lastFrameTime ? Math.min(0.1, (now - lastFrameTime) / 1000) : 0;
    lastFrameTime = now;
    const animating = isAnimating();
    if (animating) {
      time += deltaSeconds * TIME_RATE * settings.speed;
      const angle = (settings.direction * Math.PI) / 180;
      const distance = settings.flow * cellPx * deltaSeconds;
      drift = [drift[0] + Math.cos(angle) * distance, drift[1] + Math.sin(angle) * distance];
    }
    if (introArmed) {
      introArmed = false;
      introStart = now;
      introProgress = 0;
    }
    const introPlaying = introProgress < INTRO_END;
    if (introPlaying) {
      introProgress = Math.min(INTRO_END, ((now - introStart) / 1000 / settings.introDuration) * INTRO_END);
    }
    try {
      drawFrame();
    } catch (error) {
      reportFailure(error);
      return;
    }
    if (!presented) {
      presented = true;
      onReady?.();
    }
    if (animating || introPlaying) frameId = requestAnimationFrame(render);
    else lastFrameTime = 0;
  }

  const resize = () => {
    if (disposed || failed) return;
    dpr = Math.min(window.devicePixelRatio || 1, isMobile() ? settings.mobileMaxDpr : settings.maxDpr);
    const width = Math.max(1, Math.round(canvas.clientWidth * dpr));
    const height = Math.max(1, Math.round(canvas.clientHeight * dpr));
    canvas.width = width;
    canvas.height = height;
    mapView = computeMapView(settings.map, canvas.clientWidth, canvas.clientHeight);
    configureGrid();
    wakeRenderer();
  };

  const reportFailure = error => {
    if (disposed || failed) return;
    failed = true;
    if (frameId) cancelAnimationFrame(frameId);
    frameId = 0;
    teardownListeners();
    onError?.(error instanceof Error ? error : new Error(String(error)));
  };

  const handleContextLost = event => {
    event.preventDefault();
    reportFailure(new Error('WebGL context lost'));
  };

  const resizeObserver = new ResizeObserver(resize);
  const visibilityObserver = new IntersectionObserver(entries => {
    visible = entries.some(entry => entry.isIntersecting);
    if (visible) wakeRenderer();
  }, { threshold: 0 });

  function teardownListeners() {
    resizeObserver.disconnect();
    visibilityObserver.disconnect();
    document.removeEventListener('visibilitychange', handleWake);
    reduceMotion.removeEventListener('change', handleWake);
    canvas.removeEventListener('webglcontextlost', handleContextLost);
  }

  resizeObserver.observe(root);
  visibilityObserver.observe(root);
  document.addEventListener('visibilitychange', handleWake);
  reduceMotion.addEventListener('change', handleWake);
  canvas.addEventListener('webglcontextlost', handleContextLost);

  resize();
  if (settings.intro && !reduceMotion.matches) introArmed = true;

  loadImage(settings.map.src)
    .then(image => {
      if (disposed || failed) return;
      gl.bindTexture(gl.TEXTURE_2D, landMask);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE, image);
      landReady = true;
      wakeRenderer();
    })
    .catch(error => console.warn('[team-hero] map mask unavailable, rendering without it:', error));

  return {
    replay() {
      if (disposed || failed || !settings.intro || reduceMotion.matches) return;
      introArmed = true;
      wakeRenderer();
    },
    destroy() {
      disposed = true;
      if (frameId) cancelAnimationFrame(frameId);
      teardownListeners();
      gl.deleteTexture(landMask);
      gl.deleteProgram(scene.program);
      gl.deleteVertexArray(vao);
    }
  };
}

/* ---------- Mount ---------- */

function mountTeamHero() {
  const section = document.querySelector('.team-hero');
  const root = section?.querySelector('.team-hero__field');
  const canvas = root?.querySelector('canvas');
  if (!root || !canvas) return;
  try {
    createShapeWaves(root, canvas, TEAM_HERO_OPTIONS, {
      onReady: () => { section.dataset.fieldReady = 'true'; },
      onError: error => {
        console.warn('[team-hero] falling back to the HTML headline:', error);
        delete section.dataset.fieldReady;
      }
    });
  } catch (error) {
    console.warn('[team-hero] falling back to the HTML headline:', error);
  }
}

mountTeamHero();
